import subprocess, sys, time, statistics, os
def t(argv, cwd):
    s=time.perf_counter(); subprocess.run(argv,cwd=cwd,stdout=subprocess.DEVNULL,stderr=subprocess.DEVNULL); return (time.perf_counter()-s)*1000
bins = sys.argv[1].split(',')   # monokl binaries
runs=int(sys.argv[2])
sets = {
 'many': ('target/bench/stress/many', 'needle', ['rg','-n','-e','needle','.']),
 'zodbroad': ('target/bench/zod', 'string', ['rg','-n','--glob','*.ts','-e','string','.']),
 'zodid': ('target/bench/zod', 'ZodType', ['rg','-n','--glob','*.ts','-e','ZodType','.']),
}
for name,(cwd,q,rg) in sets.items():
    res={b:[] for b in bins}; res['rg']=[]
    for b in bins+['rg']: t([b,'search',q,'.'] if b!='rg' else rg, cwd)
    for _ in range(runs):
        for b in bins: res[b].append(t([b,'search',q,'.'],cwd))
        res['rg'].append(t(rg,cwd))
    r=statistics.median(res['rg'])
    print(name, ' '.join(f"{os.path.basename(os.path.dirname(b)) if b!='rg' else 'rg'}={statistics.median(v):.1f}(x{statistics.median(v)/r:.2f})" for b,v in res.items()))
EOF
